"""
Patent Intel Agent - LLM analysis schemas (Part 6)

Pydantic models defining the structured output contract for patent analysis.

DISCLAIMER: Output from this layer is AI-assisted technical analysis, NOT
legal advice. It is not a freedom-to-operate opinion, not an infringement
determination, and not a substitute for a qualified patent attorney.
"""
from typing import List, Literal, Optional

from pydantic import BaseModel, Field

LEGAL_DISCLAIMER = (
    "AI-assisted technical analysis, not legal advice. This output is "
    "generated by a language model from retrieved patent text and may be "
    "incomplete or incorrect. It is not a freedom-to-operate opinion, not an "
    "infringement or validity determination, and not a substitute for review "
    "by a qualified patent attorney."
)


class Evidence(BaseModel):
    """A single retrieved chunk cited in support of the analysis."""

    chunk_id: str = Field(..., description="ID of the retrieved chunk.")
    patent_id: str = Field(..., description="Patent the chunk belongs to.")
    section: str = Field(..., description="abstract | description | claims")
    quote: str = Field(
        ..., description="Short excerpt from the retrieved chunk."
    )
    relevance: str = Field(
        ..., description="Why this passage bears on the query."
    )


class RelevantPatent(BaseModel):
    """One patent the model judged relevant to the query."""

    patent_id: str
    title: Optional[str] = None
    relevance_score: float = Field(
        ..., ge=0.0, le=1.0,
        description="Model's own judgement of relevance, 0-1.",
    )
    summary: str = Field(..., description="What this patent covers.")
    matched_sections: List[str] = Field(
        default_factory=list,
        description="Sections that produced the match.",
    )


class PatentAnalysis(BaseModel):
    """Top-level structured response for a patent analysis request."""

    query: str
    relevant_patents: List[RelevantPatent] = Field(default_factory=list)
    overlap_summary: str = Field(
        ...,
        description="How the retrieved patents relate to the query and to "
                    "each other, including technical overlap.",
    )
    evidence: List[Evidence] = Field(default_factory=list)
    confidence: Literal["low", "medium", "high"] = Field(
        ..., description="Model's confidence given the retrieved evidence."
    )
    confidence_rationale: Optional[str] = Field(
        None, description="Why that confidence level was assigned."
    )
    disclaimer: str = Field(default=LEGAL_DISCLAIMER)
    model: Optional[str] = Field(None, description="LLM that produced this.")
    retrieval_method: Optional[str] = Field(
        None, description="Retriever used to gather the evidence."
    )


class AnalyzeRequest(BaseModel):
    """Request body for POST /analyze."""

    query: str = Field(..., min_length=1)
    top_k: int = Field(5, ge=1, le=20,
                       description="Chunks to retrieve and feed the model.")
    section: Optional[str] = None
    retrieval: Literal["hybrid", "vector", "bm25"] = Field(
        "hybrid", description="Which retriever supplies the evidence."
    )
    model: Optional[str] = Field(
        None, description="Override the configured Ollama model."
    )
    temperature: float = Field(0.1, ge=0.0, le=2.0)
